UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Sanur, Lembongan & Gili Fast Boat Tickets | NPE','$.seo_title_id','Tiket Fast Boat Sanur, Lembongan & Gili | NPE','$.seo_description_en','Book fast boat tickets from Sanur to Lembongan, Lembongan to Gili and the reverse routes. Compare available sailings and ask for a confirmed quote.','$.seo_description_id','Pesan tiket fast boat Sanur ke Lembongan, Lembongan ke Gili dan rute sebaliknya. Konfirmasi jadwal, pelabuhan dan harga sebelum bayar.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Choosing your crossing: tell us your exact departure and destination island (Gili Trawangan, Air or Meno), preferred date, number of travellers and whether you need a return. If continuing to a hotel, allow time for disembarkation and ground transfer. Ask us to confirm the actual pier, check-in deadline, baggage rules and total price before arranging your onward plans.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Memilih penyeberangan: sebutkan pulau asal dan tujuan yang tepat (Gili Trawangan, Air atau Meno), tanggal, jumlah penumpang dan kebutuhan tiket kembali. Jika melanjutkan ke hotel, sisakan waktu untuk turun dari kapal dan perjalanan darat. Konfirmasi dermaga, batas check-in, aturan bagasi dan harga total sebelum mengatur perjalanan berikutnya.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Sanur, Lembongan & Gili Fast Boat Tickets | NPE','$.seo_title_id','Tiket Fast Boat Sanur, Lembongan & Gili | NPE','$.seo_description_en','Book fast boat tickets from Sanur to Lembongan, Lembongan to Gili and the reverse routes. Compare available sailings and ask for a confirmed quote.','$.seo_description_id','Pesan tiket fast boat Sanur ke Lembongan, Lembongan ke Gili dan rute sebaliknya. Konfirmasi jadwal, pelabuhan dan harga sebelum bayar.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Choosing your crossing: tell us your exact departure and destination island (Gili Trawangan, Air or Meno), preferred date, number of travellers and whether you need a return. If continuing to a hotel, allow time for disembarkation and ground transfer. Ask us to confirm the actual pier, check-in deadline, baggage rules and total price before arranging your onward plans.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Memilih penyeberangan: sebutkan pulau asal dan tujuan yang tepat (Gili Trawangan, Air atau Meno), tanggal, jumlah penumpang dan kebutuhan tiket kembali. Jika melanjutkan ke hotel, sisakan waktu untuk turun dari kapal dan perjalanan darat. Konfirmasi dermaga, batas check-in, aturan bagasi dan harga total sebelum mengatur perjalanan berikutnya.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='boat-ticket' AND status='PUBLISHED' AND version=7 AND draft_json=published_json;
