UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Nusa Lembongan Island Tour – 3–4 Hours | NPE','$.seo_title_id','Paket Wisata Nusa Lembongan 3–4 Jam | NPE','$.seo_description_en','Plan a Nusa Lembongan island tour to Dream Beach, Devil’s Tears, Mangrove Point and Yellow Bridge. Ask about pickup, optional stops and the quote.','$.seo_description_id','Rencanakan tour Nusa Lembongan ke Dream Beach, Devil’s Tears, Mangrove Point dan Yellow Bridge. Konfirmasi penjemputan, pilihan destinasi dan harga.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'How to plan your day: guests already staying on Lembongan can arrange a pickup point on the island. If starting in Sanur, arrange the crossing separately and leave a buffer before the return boat. Tell us if you prefer beach stops, coastal viewpoints or a relaxed pace. Ask which entrance fees, parking and other costs are included rather than assuming that every extra is covered.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Cara merencanakan perjalanan: tamu yang menginap di Lembongan dapat menentukan titik jemput di pulau. Jika berangkat dari Sanur, atur penyeberangan terpisah dan sisakan waktu sebelum kapal kembali. Sampaikan jika lebih menyukai pantai, panorama tebing atau perjalanan santai. Konfirmasi tiket masuk, parkir dan biaya lainnya agar tidak mengasumsikan semua tambahan sudah termasuk.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Nusa Lembongan Island Tour – 3–4 Hours | NPE','$.seo_title_id','Paket Wisata Nusa Lembongan 3–4 Jam | NPE','$.seo_description_en','Plan a Nusa Lembongan island tour to Dream Beach, Devil’s Tears, Mangrove Point and Yellow Bridge. Ask about pickup, optional stops and the quote.','$.seo_description_id','Rencanakan tour Nusa Lembongan ke Dream Beach, Devil’s Tears, Mangrove Point dan Yellow Bridge. Konfirmasi penjemputan, pilihan destinasi dan harga.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'How to plan your day: guests already staying on Lembongan can arrange a pickup point on the island. If starting in Sanur, arrange the crossing separately and leave a buffer before the return boat. Tell us if you prefer beach stops, coastal viewpoints or a relaxed pace. Ask which entrance fees, parking and other costs are included rather than assuming that every extra is covered.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Cara merencanakan perjalanan: tamu yang menginap di Lembongan dapat menentukan titik jemput di pulau. Jika berangkat dari Sanur, atur penyeberangan terpisah dan sisakan waktu sebelum kapal kembali. Sampaikan jika lebih menyukai pantai, panorama tebing atau perjalanan santai. Konfirmasi tiket masuk, parkir dan biaya lainnya agar tidak mengasumsikan semua tambahan sudah termasuk.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour' AND status='PUBLISHED' AND version=10 AND draft_json=published_json;
INSERT OR IGNORE INTO website_activity_revisions(id,activity_id,version,snapshot_json) SELECT 'seo-20261128-'||id,id,version,published_json FROM website_activities WHERE slug='nusa-lembongan-island-tour' AND status='PUBLISHED' AND version=11 AND draft_json=published_json AND json_extract(published_json,'$.seo_title_en')='Nusa Lembongan Island Tour – 3–4 Hours | NPE' AND instr(json_extract(published_json,'$.description_en'),'How to plan your day: guests already staying on Lembongan can arrange a pickup point on the island. If starting in Sanur, arrange the crossing separately and leave a buffer before the return boat. Tell us if you prefer beach stops, coastal viewpoints or a relaxed pace. Ask which entrance fees, parking and other costs are included rather than assuming that every extra is covered.')>0;
UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Devil’s Tears Nusa Lembongan – Visitor Guide | NPE','$.seo_title_id','Devil’s Tears Nusa Lembongan – Panduan Wisata | NPE','$.seo_description_en','Visit Devil’s Tears (Devil’s Tear), a coastal viewpoint on Nusa Lembongan. Learn how to plan your visit, stay safe near the waves and combine Dream Beach.','$.seo_description_id','Panduan mengunjungi Devil’s Tears di Nusa Lembongan: panorama tebing, keselamatan dekat ombak, dan pilihan singgah ke Dream Beach dalam island tour.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Planning your visit: Devil’s Tears (also called Devil’s Tear) is a viewpoint, not a swimming spot. Wave surges can reach the rocky platform unexpectedly; stay behind barriers, away from exposed edges, and follow local instructions. Do not approach the water for a photo. Combine this stop with nearby Dream Beach if access and sea conditions permit. Ask the operator about admission, walking access and the most suitable timing for your visit; no particular wave display or sunset view is guaranteed.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Rencana kunjungan: Devil’s Tears (juga disebut Devil’s Tear) adalah titik pandang, bukan tempat berenang. Semburan ombak bisa menjangkau tebing secara tiba-tiba; tetap di belakang pembatas, jauhi tepi terbuka dan ikuti arahan setempat. Jangan mendekati air demi foto. Padukan kunjungan dengan Dream Beach jika akses dan kondisi memungkinkan. Konfirmasi tiket masuk, akses berjalan kaki dan waktu kunjungan dengan operator; semburan ombak atau pemandangan matahari terbenam tidak dapat dijamin.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Devil’s Tears Nusa Lembongan – Visitor Guide | NPE','$.seo_title_id','Devil’s Tears Nusa Lembongan – Panduan Wisata | NPE','$.seo_description_en','Visit Devil’s Tears (Devil’s Tear), a coastal viewpoint on Nusa Lembongan. Learn how to plan your visit, stay safe near the waves and combine Dream Beach.','$.seo_description_id','Panduan mengunjungi Devil’s Tears di Nusa Lembongan: panorama tebing, keselamatan dekat ombak, dan pilihan singgah ke Dream Beach dalam island tour.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Planning your visit: Devil’s Tears (also called Devil’s Tear) is a viewpoint, not a swimming spot. Wave surges can reach the rocky platform unexpectedly; stay behind barriers, away from exposed edges, and follow local instructions. Do not approach the water for a photo. Combine this stop with nearby Dream Beach if access and sea conditions permit. Ask the operator about admission, walking access and the most suitable timing for your visit; no particular wave display or sunset view is guaranteed.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Rencana kunjungan: Devil’s Tears (juga disebut Devil’s Tear) adalah titik pandang, bukan tempat berenang. Semburan ombak bisa menjangkau tebing secara tiba-tiba; tetap di belakang pembatas, jauhi tepi terbuka dan ikuti arahan setempat. Jangan mendekati air demi foto. Padukan kunjungan dengan Dream Beach jika akses dan kondisi memungkinkan. Konfirmasi tiket masuk, akses berjalan kaki dan waktu kunjungan dengan operator; semburan ombak atau pemandangan matahari terbenam tidak dapat dijamin.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour-devil-s-tear' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
INSERT OR IGNORE INTO website_activity_revisions(id,activity_id,version,snapshot_json) SELECT 'seo-20261128-'||id,id,version,published_json FROM website_activities WHERE slug='nusa-lembongan-island-tour-devil-s-tear' AND status='PUBLISHED' AND version=3 AND draft_json=published_json AND json_extract(published_json,'$.seo_title_en')='Devil’s Tears Nusa Lembongan – Visitor Guide | NPE' AND instr(json_extract(published_json,'$.description_en'),'Planning your visit: Devil’s Tears (also called Devil’s Tear) is a viewpoint, not a swimming spot. Wave surges can reach the rocky platform unexpectedly; stay behind barriers, away from exposed edges, and follow local instructions. Do not approach the water for a photo. Combine this stop with nearby Dream Beach if access and sea conditions permit. Ask the operator about admission, walking access and the most suitable timing for your visit; no particular wave display or sunset view is guaranteed.')>0;
UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Dream Beach Nusa Lembongan – Visitor Guide | NPE','$.seo_title_id','Dream Beach Nusa Lembongan – Panduan Pantai | NPE','$.seo_description_en','Discover Dream Beach on Nusa Lembongan, near Devil’s Tears. Plan a beach viewpoint stop, check sea conditions and ask about an island tour.','$.seo_description_id','Kenali Dream Beach di Nusa Lembongan dekat Devil’s Tears. Nikmati panorama pantai, perhatikan kondisi ombak, dan rencanakan island tour.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Dream Beach is on Nusa Lembongan, not the main island of Nusa Penida. It is a lovely stop for coastal views, but strong surf and currents can make swimming unsuitable. Follow local warnings; enjoy the view from shore when conditions are uncertain. Ask about beach access, walking distance, shade and any charges before visiting. A combined stop at Devil’s Tears can fit the island tour depending on access and time.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Dream Beach berada di Nusa Lembongan, bukan di pulau utama Nusa Penida. Pantai ini menarik untuk menikmati panorama, tetapi ombak dan arus kuat dapat membuat berenang tidak sesuai. Ikuti peringatan setempat dan nikmati pemandangan dari darat jika kondisi meragukan. Tanyakan akses pantai, jarak berjalan, tempat berteduh dan biaya sebelum berkunjung. Kunjungan dapat digabung dengan Devil’s Tears sesuai waktu dan akses.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Dream Beach Nusa Lembongan – Visitor Guide | NPE','$.seo_title_id','Dream Beach Nusa Lembongan – Panduan Pantai | NPE','$.seo_description_en','Discover Dream Beach on Nusa Lembongan, near Devil’s Tears. Plan a beach viewpoint stop, check sea conditions and ask about an island tour.','$.seo_description_id','Kenali Dream Beach di Nusa Lembongan dekat Devil’s Tears. Nikmati panorama pantai, perhatikan kondisi ombak, dan rencanakan island tour.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Dream Beach is on Nusa Lembongan, not the main island of Nusa Penida. It is a lovely stop for coastal views, but strong surf and currents can make swimming unsuitable. Follow local warnings; enjoy the view from shore when conditions are uncertain. Ask about beach access, walking distance, shade and any charges before visiting. A combined stop at Devil’s Tears can fit the island tour depending on access and time.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Dream Beach berada di Nusa Lembongan, bukan di pulau utama Nusa Penida. Pantai ini menarik untuk menikmati panorama, tetapi ombak dan arus kuat dapat membuat berenang tidak sesuai. Ikuti peringatan setempat dan nikmati pemandangan dari darat jika kondisi meragukan. Tanyakan akses pantai, jarak berjalan, tempat berteduh dan biaya sebelum berkunjung. Kunjungan dapat digabung dengan Devil’s Tears sesuai waktu dan akses.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour-dream-beach' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
INSERT OR IGNORE INTO website_activity_revisions(id,activity_id,version,snapshot_json) SELECT 'seo-20261128-'||id,id,version,published_json FROM website_activities WHERE slug='nusa-lembongan-island-tour-dream-beach' AND status='PUBLISHED' AND version=3 AND draft_json=published_json AND json_extract(published_json,'$.seo_title_en')='Dream Beach Nusa Lembongan – Visitor Guide | NPE' AND instr(json_extract(published_json,'$.description_en'),'Dream Beach is on Nusa Lembongan, not the main island of Nusa Penida. It is a lovely stop for coastal views, but strong surf and currents can make swimming unsuitable. Follow local warnings; enjoy the view from shore when conditions are uncertain. Ask about beach access, walking distance, shade and any charges before visiting. A combined stop at Devil’s Tears can fit the island tour depending on access and time.')>0;
UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Yellow Bridge Nusa Lembongan & Ceningan | NPE','$.seo_title_id','Yellow Bridge Nusa Lembongan–Ceningan | NPE','$.seo_description_en','Explore Yellow Bridge connecting Lembongan and Ceningan. Plan a photo stop, respect local traffic and confirm your island tour route.','$.seo_description_id','Kunjungi Yellow Bridge penghubung Lembongan dan Ceningan. Rencanakan singgah foto, hormati lalu lintas warga dan konfirmasi rute wisata.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'For a photo stop, choose a place off the traffic path and keep access clear for residents. The bridge connects two islands, but crossing it and touring Ceningan are different from simply visiting the viewpoint. Confirm permitted transport, any walking or onward transfer, and whether Ceningan stops are included in your booking.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Saat singgah untuk foto, pilih tempat di luar jalur lalu lintas dan jangan menghalangi akses warga. Jembatan ini menghubungkan dua pulau, tetapi menyeberang dan menjelajahi Ceningan berbeda dengan sekadar mengunjungi titik pandang. Konfirmasi kendaraan yang diizinkan, kebutuhan berjalan atau transfer lanjutan, dan apakah kunjungan Ceningan termasuk dalam pemesanan.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Yellow Bridge Nusa Lembongan & Ceningan | NPE','$.seo_title_id','Yellow Bridge Nusa Lembongan–Ceningan | NPE','$.seo_description_en','Explore Yellow Bridge connecting Lembongan and Ceningan. Plan a photo stop, respect local traffic and confirm your island tour route.','$.seo_description_id','Kunjungi Yellow Bridge penghubung Lembongan dan Ceningan. Rencanakan singgah foto, hormati lalu lintas warga dan konfirmasi rute wisata.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'For a photo stop, choose a place off the traffic path and keep access clear for residents. The bridge connects two islands, but crossing it and touring Ceningan are different from simply visiting the viewpoint. Confirm permitted transport, any walking or onward transfer, and whether Ceningan stops are included in your booking.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Saat singgah untuk foto, pilih tempat di luar jalur lalu lintas dan jangan menghalangi akses warga. Jembatan ini menghubungkan dua pulau, tetapi menyeberang dan menjelajahi Ceningan berbeda dengan sekadar mengunjungi titik pandang. Konfirmasi kendaraan yang diizinkan, kebutuhan berjalan atau transfer lanjutan, dan apakah kunjungan Ceningan termasuk dalam pemesanan.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour-yellow-bridge' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
