UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Nusa Lembongan Mangrove Forest – Land Visit | NPE','$.seo_title_id','Hutan Mangrove Nusa Lembongan – Wisata Darat | NPE','$.seo_description_en','Explore the onshore mangrove area of Nusa Lembongan. Learn the difference between a land stop, optional boat trip and offshore snorkeling.','$.seo_description_id','Jelajahi hutan mangrove Nusa Lembongan dari darat. Ketahui perbedaan singgah darat, susur mangrove dengan perahu dan snorkeling di laut.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'This island-tour stop is a land visit near the mangroves. A boat ride or kayak through the waterways is a separate optional activity, and the offshore Mangrove Point snorkeling site is a different experience. Ask which activity is available, what is included, and whether tides affect access. Respect the roots, wildlife and local access rules.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Singgah dalam island tour ini adalah kunjungan darat di kawasan mangrove. Susur saluran bakau dengan perahu atau kayak adalah aktivitas tambahan terpisah, sedangkan snorkeling Mangrove Point di lepas pantai merupakan pengalaman berbeda. Tanyakan pilihan yang tersedia, fasilitas dan pengaruh pasang surut terhadap akses. Hormati akar bakau, satwa dan aturan akses setempat.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Nusa Lembongan Mangrove Forest – Land Visit | NPE','$.seo_title_id','Hutan Mangrove Nusa Lembongan – Wisata Darat | NPE','$.seo_description_en','Explore the onshore mangrove area of Nusa Lembongan. Learn the difference between a land stop, optional boat trip and offshore snorkeling.','$.seo_description_id','Jelajahi hutan mangrove Nusa Lembongan dari darat. Ketahui perbedaan singgah darat, susur mangrove dengan perahu dan snorkeling di laut.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'This island-tour stop is a land visit near the mangroves. A boat ride or kayak through the waterways is a separate optional activity, and the offshore Mangrove Point snorkeling site is a different experience. Ask which activity is available, what is included, and whether tides affect access. Respect the roots, wildlife and local access rules.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Singgah dalam island tour ini adalah kunjungan darat di kawasan mangrove. Susur saluran bakau dengan perahu atau kayak adalah aktivitas tambahan terpisah, sedangkan snorkeling Mangrove Point di lepas pantai merupakan pengalaman berbeda. Tanyakan pilihan yang tersedia, fasilitas dan pengaruh pasang surut terhadap akses. Hormati akar bakau, satwa dan aturan akses setempat.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour-mangrove-point' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
