UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Panorama Point Nusa Lembongan – Viewpoint | NPE','$.seo_title_id','Panorama Point Nusa Lembongan – Titik Pandang | NPE','$.seo_description_en','See the Jungutbatu coastline from Panorama Point in Nusa Lembongan. Plan an optional viewpoint stop and enjoy distant Bali views on clear days.','$.seo_description_id','Nikmati panorama pesisir Jungutbatu dari Panorama Point Nusa Lembongan. Rencanakan singgah opsional dan nikmati pemandangan Bali saat cerah.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'This is a viewpoint stop rather than a beach activity. Clear skies offer the best chance of distant views, but mountain visibility varies. Ask whether the stop is included in your chosen island tour and whether the vehicle can reach a suitable stopping point. Stay away from road traffic and exposed edges when taking photographs.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Ini adalah singgah di titik pandang, bukan aktivitas pantai. Langit cerah memberi kesempatan melihat lanskap jauh, tetapi visibilitas gunung dapat berubah. Tanyakan apakah singgah ini termasuk dalam island tour dan apakah kendaraan dapat mencapai tempat berhenti yang sesuai. Jauhi lalu lintas dan tepi terbuka saat mengambil foto.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Panorama Point Nusa Lembongan – Viewpoint | NPE','$.seo_title_id','Panorama Point Nusa Lembongan – Titik Pandang | NPE','$.seo_description_en','See the Jungutbatu coastline from Panorama Point in Nusa Lembongan. Plan an optional viewpoint stop and enjoy distant Bali views on clear days.','$.seo_description_id','Nikmati panorama pesisir Jungutbatu dari Panorama Point Nusa Lembongan. Rencanakan singgah opsional dan nikmati pemandangan Bali saat cerah.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'This is a viewpoint stop rather than a beach activity. Clear skies offer the best chance of distant views, but mountain visibility varies. Ask whether the stop is included in your chosen island tour and whether the vehicle can reach a suitable stopping point. Stay away from road traffic and exposed edges when taking photographs.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Ini adalah singgah di titik pandang, bukan aktivitas pantai. Langit cerah memberi kesempatan melihat lanskap jauh, tetapi visibilitas gunung dapat berubah. Tanyakan apakah singgah ini termasuk dalam island tour dan apakah kendaraan dapat mencapai tempat berhenti yang sesuai. Jauhi lalu lintas dan tepi terbuka saat mengambil foto.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour-panorama-point' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
