UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Mahagiri Beach Nusa Lembongan – Visitor Guide | NPE','$.seo_title_id','Mahagiri Beach Nusa Lembongan – Panduan Pantai | NPE','$.seo_description_en','Visit Mahagiri Beach near Jungutbatu for coastal scenery and a relaxed island tour stop. Confirm access, sea conditions and optional charges.','$.seo_description_id','Kunjungi Mahagiri Beach dekat Jungutbatu untuk panorama pesisir dan singgah santai. Konfirmasi akses, kondisi laut dan biaya tambahan.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Plan Mahagiri as a relaxed optional coastal stop, subject to your itinerary. Public beach access and access to privately operated facilities are not the same; confirm where you can enter and any separate charges. Water conditions change with tide and weather, so do not assume the beach is suitable for swimming. Ask about walking access and a suitable time for photos.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Rencanakan Mahagiri sebagai singgah pesisir opsional sesuai itinerary. Akses pantai dan fasilitas yang dikelola pihak swasta tidak selalu sama; konfirmasi jalur masuk dan biaya terpisah. Kondisi air berubah mengikuti pasang surut dan cuaca, sehingga jangan mengasumsikan pantai selalu cocok untuk berenang. Tanyakan akses berjalan kaki dan waktu yang sesuai untuk foto.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Mahagiri Beach Nusa Lembongan – Visitor Guide | NPE','$.seo_title_id','Mahagiri Beach Nusa Lembongan – Panduan Pantai | NPE','$.seo_description_en','Visit Mahagiri Beach near Jungutbatu for coastal scenery and a relaxed island tour stop. Confirm access, sea conditions and optional charges.','$.seo_description_id','Kunjungi Mahagiri Beach dekat Jungutbatu untuk panorama pesisir dan singgah santai. Konfirmasi akses, kondisi laut dan biaya tambahan.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'Plan Mahagiri as a relaxed optional coastal stop, subject to your itinerary. Public beach access and access to privately operated facilities are not the same; confirm where you can enter and any separate charges. Water conditions change with tide and weather, so do not assume the beach is suitable for swimming. Ask about walking access and a suitable time for photos.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Rencanakan Mahagiri sebagai singgah pesisir opsional sesuai itinerary. Akses pantai dan fasilitas yang dikelola pihak swasta tidak selalu sama; konfirmasi jalur masuk dan biaya terpisah. Kondisi air berubah mengikuti pasang surut dan cuaca, sehingga jangan mengasumsikan pantai selalu cocok untuk berenang. Tanyakan akses berjalan kaki dan waktu yang sesuai untuk foto.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='nusa-lembongan-island-tour-mahagiri-beach' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
