UPDATE website_activities SET published_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Mangrove Point Nusa Lembongan Snorkeling | NPE','$.seo_title_id','Snorkeling Mangrove Point Nusa Lembongan | NPE','$.seo_description_en','Plan guided snorkeling at Mangrove Point off Nusa Lembongan. Ask about reef conditions, currents, equipment and availability on your route.','$.seo_description_id','Rencanakan snorkeling berpemandu di Mangrove Point lepas pantai Nusa Lembongan. Konfirmasi arus, perlengkapan dan ketersediaan rute.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'This is the offshore reef site, not the mangrove forest land visit. Currents and visibility vary; enter the water only when the guide confirms conditions are suitable for your group. Tell the operator about swimming ability and ask about flotation equipment, briefing, entry and exit arrangements. Never touch coral or chase marine animals; wildlife sightings and specific stops are not guaranteed. Confirm whether Mangrove Point can be included on your selected snorkeling trip.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Ini adalah lokasi terumbu di lepas pantai, bukan kunjungan darat ke hutan mangrove. Arus dan visibilitas berubah; masuk ke air hanya jika pemandu memastikan kondisi sesuai kemampuan kelompok. Sampaikan kemampuan berenang dan tanyakan alat apung, briefing serta pengaturan masuk dan keluar air. Jangan menyentuh karang atau mengejar satwa; kemunculan biota dan titik kunjungan tertentu tidak dijamin. Konfirmasi apakah Mangrove Point tersedia untuk paket snorkeling yang dipilih.'),draft_json=json_set(published_json,'$.seo_mode','MANUAL','$.seo_title_en','Mangrove Point Nusa Lembongan Snorkeling | NPE','$.seo_title_id','Snorkeling Mangrove Point Nusa Lembongan | NPE','$.seo_description_en','Plan guided snorkeling at Mangrove Point off Nusa Lembongan. Ask about reef conditions, currents, equipment and availability on your route.','$.seo_description_id','Rencanakan snorkeling berpemandu di Mangrove Point lepas pantai Nusa Lembongan. Konfirmasi arus, perlengkapan dan ketersediaan rute.','$.description_en',json_extract(published_json,'$.description_en')||char(10)||char(10)||'This is the offshore reef site, not the mangrove forest land visit. Currents and visibility vary; enter the water only when the guide confirms conditions are suitable for your group. Tell the operator about swimming ability and ask about flotation equipment, briefing, entry and exit arrangements. Never touch coral or chase marine animals; wildlife sightings and specific stops are not guaranteed. Confirm whether Mangrove Point can be included on your selected snorkeling trip.','$.description_id',json_extract(published_json,'$.description_id')||char(10)||char(10)||'Ini adalah lokasi terumbu di lepas pantai, bukan kunjungan darat ke hutan mangrove. Arus dan visibilitas berubah; masuk ke air hanya jika pemandu memastikan kondisi sesuai kemampuan kelompok. Sampaikan kemampuan berenang dan tanyakan alat apung, briefing serta pengaturan masuk dan keluar air. Jangan menyentuh karang atau mengejar satwa; kemunculan biota dan titik kunjungan tertentu tidak dijamin. Konfirmasi apakah Mangrove Point tersedia untuk paket snorkeling yang dipilih.'),version=version+1,published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE slug='snorkeling-mangrove-point' AND status='PUBLISHED' AND version=2 AND draft_json=published_json;
INSERT OR IGNORE INTO website_activity_revisions(id,activity_id,version,snapshot_json) SELECT 'seo-20261128-'||id,id,version,published_json FROM website_activities WHERE slug='snorkeling-mangrove-point' AND status='PUBLISHED' AND version=3 AND draft_json=published_json AND json_extract(published_json,'$.seo_title_en')='Mangrove Point Nusa Lembongan Snorkeling | NPE' AND instr(json_extract(published_json,'$.description_en'),'This is the offshore reef site, not the mangrove forest land visit. Currents and visibility vary; enter the water only when the guide confirms conditions are suitable for your group. Tell the operator about swimming ability and ask about flotation equipment, briefing, entry and exit arrangements. Never touch coral or chase marine animals; wildlife sightings and specific stops are not guaranteed. Confirm whether Mangrove Point can be included on your selected snorkeling trip.')>0;
